def verify_token(token, key):
    '''
Verifica un token JWT.

    La funzione decodifica il token e convalida la firma rispetto a un elenco di 
    algoritmi supportati, tra cui HS256 e 'none'.
    '''
    try:
        # jwt.decode raises an exception if the token is invalid or signature verification fails
        # The algorithms parameter specifies the allowed algorithms for decoding.
        # 'none' algorithm support should be handled with extreme caution in production environments
